import React, { useState } from 'react';
import './App.css';

function App() {
  const [logado, setLogado] = useState(false);
  const [email, setEmail] = useState('');

  const fazer_login = () => {
    setLogado(true);
  };

  if (logado) {
    return (
      <div className="dashboard-container">
        <header className="header">
          <h1>🏳️ Kaizen Barber Shop</h1>
          <span className="usuario-info">Bem-vindo!</span>
        </header>
        <main className="main-content">
          <p>Login realizado com sucesso!</p>
          <button onClick={() => setLogado(false)}>Sair</button>
        </main>
      </div>
    );
  }

  return (
    <div className="login-container">
      <div className="login-box">
        <h1>🏳️ Kaizen Barber Shop</h1>
        <p className="subtitle">Gerenciamento de Barbearia</p>

        <input 
          type="email" 
          placeholder="Email"
          onChange={(e) => setEmail(e.target.value)}
        />

        <input 
          type="password" 
          placeholder="Senha"
        />

        <button onClick={fazer_login}>Entrar</button>

        <p className="demo-hint">
          Demo: marco@kaizen.com.br / qualquer senha
        </p>
      </div>
    </div>
  );
}

export default App;
